export type CalculatorCategory = 'health' | 'finance' | 'math' | 'conversion' | 'everyday' | 'education'

export interface CalculatorExample {
  inputs: string
  calculation: string
  result: string
}

export interface Calculator {
  id: string
  name: string
  description: string
  category: CalculatorCategory
  icon: string
  path: string
  fields: CalculatorField[]
  formula: string
  calculate: (values: Record<string, number>) => CalculationResult
  explanation: string
  example: CalculatorExample
  faq: [string, string][]
  related: string[]
}

import { calculateScientific } from '../lib/scientificParser'

export interface CalculatorField {
  id: string
  label: string
  unit?: string
  min?: number
  max?: number
  step?: string
  defaultValue?: string
  type?: 'select'
  options?: { value: number; label: string }[]
}

export interface CalculationResult {
  headline: string
  details: string[]
  steps?: string[]
}

const n = (value: number, digits = 2) => value.toLocaleString(undefined, { maximumFractionDigits: digits })
// Currency must always show two decimal places ($1,199.10, not $1,199.1).
// n() deliberately keeps only a maximum, so money() sets a minimum too.
const money = (value: number) => value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })
const field = (id: string, label: string, unit: string, min = 0, max?: number): CalculatorField => ({ id, label, unit, min, max, step: 'any' })
const selectField = (id: string, label: string, options: { value: number; label: string }[]): CalculatorField => ({ id, label, type: 'select', options, min: 0, max: options.length - 1, defaultValue: String(options[0].value) })
const sexField = (): CalculatorField => selectField('sex', 'Sex', [{ value: 1, label: 'Male' }, { value: 0, label: 'Female' }])

const definitions: Calculator[] = [
  {
    id: 'bmi', name: 'BMI Calculator', description: 'Calculate body mass index and understand the standard weight category.', category: 'health', icon: '⚖', path: '/calculators/bmi',
    fields: [field('weight', 'Weight', 'kg', 1, 500), field('height', 'Height', 'cm', 30, 280)], formula: 'BMI = weight (kg) ÷ height (m)²',
    calculate: ({ weight, height }) => { const value = weight / ((height / 100) ** 2); const category = value < 18.5 ? 'Underweight' : value < 25 ? 'Normal weight' : value < 30 ? 'Overweight' : 'Obese'; return { headline: `${n(value)} — ${category}`, details: ['BMI is a screening measure, not a diagnosis.'], steps: [`Height converted to ${n(height / 100, 2)} m`, `BMI = ${n(weight)} ÷ (${n(height / 100, 2)} × ${n(height / 100, 2)})`, `Your BMI is ${n(value)}`] } }, explanation: "Body mass index (BMI) is a simple number that relates your weight to your height. It is widely used as a first check of whether your weight falls in the underweight, normal weight, overweight or obese range, and people use it to track how their weight changes over time.\n\nThe calculator divides your weight in kilograms by your height in metres squared. A result below 18.5 is classed as underweight, 18.5 to 24.9 as normal weight, 25 to 29.9 as overweight, and 30 or above as obese. BMI is a screening measure, not a diagnosis, and it cannot tell muscle apart from fat, so the result is informational and is not a substitute for professional medical advice.", example: { inputs: "Weight 70 kg, height 175 cm.", calculation: "Convert height to metres: 175 ÷ 100 = 1.75 m. Square it: 1.75 × 1.75 = 3.0625. Divide weight by that: 70 ÷ 3.0625 = 22.86.", result: "22.86 — Normal weight." }, faq: [["Why does BMI use height squared instead of just height?", "Height is squared because weight does not grow in a straight line with height. Squaring keeps the number comparable between short and tall people, so a tall person is not automatically classed as overweight."], ["Can two people with the same BMI look very different?", "Yes. BMI only uses weight and height, so it cannot tell muscle apart from fat. A very muscular person and a person with more body fat can share the same BMI while having quite different body compositions."], ["Should I use BMI for a child or a pregnant woman?", "No. The adult categories shown here do not apply to children, whose BMI is judged against age and sex growth charts, or to pregnancy, where weight changes are expected. Ask a doctor for the right measure in those cases."]], related: ['calorie', 'ideal-weight'],
  },
  {
    id: 'bmr', name: 'BMR Calculator', description: 'Estimate how many calories your body uses at rest.', category: 'health', icon: '🔥', path: '/calculators/bmr',
    fields: [field('weight', 'Weight', 'kg', 1, 500), field('height', 'Height', 'cm', 30, 280), field('age', 'Age', 'years', 13, 120), sexField()], formula: 'Mifflin–St Jeor: BMR = 10w + 6.25h − 5a + s',
    calculate: ({ weight, height, age, sex }) => { const value = 10 * weight + 6.25 * height - 5 * age + (sex ? 5 : -161); return { headline: `${n(value, 0)} calories/day`, details: ['This is an estimate of resting energy expenditure.'], steps: [`10 × ${n(weight)} + 6.25 × ${n(height)} − 5 × ${n(age)} + ${sex ? 5 : '−161'}`, `Estimated BMR: ${n(value, 0)} calories/day`] } }, explanation: "Your basal metabolic rate (BMR) is the number of calories your body burns at rest in a day — the energy needed to keep you breathing, keep your heart beating and maintain your body temperature, before any movement or exercise. Knowing it helps you set a sensible daily calorie target, whether you want to lose, gain or maintain weight.\n\nThis calculator uses the Mifflin–St Jeor equation, which estimates BMR from your weight, height, age and sex. It is one of the most widely used formulas for this purpose, but it is still an estimate: real energy use varies with muscle mass, health and other factors. The result is informational and is not a substitute for professional medical advice.", example: { inputs: "Male, weight 70 kg, height 175 cm, age 30 years.", calculation: "10 × 70 + 6.25 × 175 − 5 × 30 + 5 = 700 + 1,093.75 − 150 + 5 = 1,648.75.", result: "1,649 calories/day." }, faq: [["Why does the formula add 5 for men and subtract 161 for women?", "Men and women differ on average in muscle mass and body composition, which affects resting energy use. The Mifflin–St Jeor equation includes these fixed adjustments so the same formula can estimate BMR for both sexes."], ["Does my BMR change as I get older?", "Yes, it usually falls with age. The formula subtracts 5 calories for each year of age, reflecting the gradual loss of muscle and slower metabolism that typically comes with ageing. Recheck your BMR every few years."], ["Is my BMR the same as the calories I need each day?", "No. BMR covers only resting energy use. Your total daily need is higher because it adds the calories burned by moving, working, exercising and digesting food. Use the calorie calculator to combine your BMR with an activity level."]], related: ['calorie', 'water-intake'],
  },
  {
    id: 'body-fat', name: 'Body Fat Calculator', description: 'Estimate body fat percentage using the U.S. Navy method.', category: 'health', icon: '◉', path: '/calculators/body-fat',
    fields: [field('waist', 'Waist circumference', 'cm', 30, 250), field('neck', 'Neck circumference', 'cm', 15, 100), field('hip', 'Hip circumference (use 0 for male)', 'cm', 0, 250), field('height', 'Height', 'cm', 80, 280), sexField()], formula: 'U.S. Navy circumference method (logarithmic estimate)',
    calculate: ({ waist, neck, hip, height, sex }) => { const value = sex ? 495 / (1.0324 - 0.19077 * Math.log10(waist - neck) + 0.15456 * Math.log10(height)) - 450 : 495 / (1.29579 - 0.35004 * Math.log10(waist + hip - neck) + 0.221 * Math.log10(height)) - 450; return { headline: `${n(Math.max(0, value))}% estimated body fat`, details: ['The U.S. Navy method is an estimate and can vary with measurement technique.'] } }, explanation: "Body fat percentage is the share of your total weight that is fat, as opposed to muscle, bone and other tissue. It gives a clearer picture of body composition than weight alone: two people of the same weight can have very different body fat percentages. People use it to track fitness progress or to understand their health risks.\n\nThis calculator uses the U.S. Navy circumference method, which estimates body fat from waist, neck and height measurements (and hip measurements for women) using a logarithmic formula. It is a rough estimate — tape measurements vary with technique and the method was developed on military populations — so the result is informational and is not a substitute for professional medical advice.", example: { inputs: "Male, waist 90 cm, neck 40 cm, height 175 cm (hip 0).", calculation: "Waist minus neck is 50 cm. Using the U.S. Navy formula: 495 ÷ (1.0324 − 0.19077 × log10(50) + 0.15456 × log10(175)) − 450 = 495 ÷ 1.05497 − 450 = 19.21.", result: "19.21% estimated body fat." }, faq: [["Why does the calculator ask for my neck measurement?", "The Navy method compares waist and neck sizes. A larger neck relative to the waist suggests more muscle in the upper body, which lowers the estimated body fat, while a larger waist suggests more fat around the middle."], ["Why do women enter a hip measurement but men enter 0?", "The Navy formula for women includes hip size because fat is distributed differently between the sexes. For men the formula uses only waist, neck and height, so the hip field should be left at 0."], ["How accurate is a tape-measure body fat estimate?", "It is a rough estimate that can vary by several percentage points, and it depends on measuring in the right places with a level tape. For a precise measurement, methods such as a DEXA scan are far more reliable."]], related: ['bmi', 'ideal-weight'],
  },
  {
    id: 'ideal-weight', name: 'Ideal Weight Calculator', description: 'Estimate an ideal weight range using the Devine formula.', category: 'health', icon: '♥', path: '/calculators/ideal-weight', fields: [field('height', 'Height', 'cm', 120, 240), sexField()], formula: 'Devine: male 50 + 2.3 × inches over 5 ft; female 45.5 + 2.3 × inches over 5 ft', calculate: ({ height, sex }) => { const inches = height / 2.54; const value = (sex ? 50 : 45.5) + 2.3 * Math.max(0, inches - 60); return { headline: `${n(value)} kg`, details: ['This is a population estimate, not a medical target.'], steps: [`Height: ${n(inches)} inches`, `Estimated ideal weight: ${n(value)} kg`] } }, explanation: "Ideal weight is a single estimated weight for your height, based on the Devine formula, which was originally developed to work out drug doses. It gives one number rather than a range, and people use it as a rough reference point when thinking about a healthy weight for their height.\n\nThe formula starts from 50 kg for a man or 45.5 kg for a woman at 5 feet tall, then adds 2.3 kg for each inch above 5 feet. It does not account for muscle, frame size or age, so it is a population estimate rather than a personal target. The result is informational and is not a substitute for professional medical advice.", example: { inputs: "Male, height 175 cm.", calculation: "Convert to inches: 175 ÷ 2.54 = 68.8976 inches. Subtract 5 feet (60 inches) to get 8.8976 inches over 5 feet. Ideal weight = 50 + 2.3 × 8.8976 = 50 + 20.46 = 70.46 kg.", result: "70.46 kg." }, faq: [["Why is the ideal weight different for men and women of the same height?", "The Devine formula starts from a higher base weight for men (50 kg) than for women (45.5 kg) at 5 feet tall, reflecting differences in muscle mass and build between the sexes. The 2.3 kg per inch above 5 feet is the same for both."], ["My ideal weight is below my current weight. Should I aim for it exactly?", "Not necessarily. The Devine formula gives one number for a population average and ignores muscle, frame size and age. Treat it as a rough guide, and talk to a doctor before setting a weight goal."], ["Does the calculator work for people under 5 feet tall?", "Yes, but the result will be the base weight — 50 kg for men or 45.5 kg for women — because the formula only adds weight for inches above 5 feet and never subtracts for shorter heights."]], related: ['bmi', 'calorie'],
  },
  {
    id: 'calorie', name: 'Calorie Calculator', description: 'Estimate daily calories based on BMR and activity level.', category: 'health', icon: '✦', path: '/calculators/calorie', fields: [field('bmr', 'BMR', 'calories', 500, 5000), field('activity', 'Activity multiplier', '×', 1, 2.5)], formula: 'Daily calories = BMR × activity multiplier', calculate: ({ bmr, activity }) => { const value = bmr * activity; return { headline: `${n(value, 0)} calories/day`, details: ['Use this as a starting point and adjust based on real-world results.'], steps: [`${n(bmr, 0)} × ${n(activity, 2)} = ${n(value, 0)} calories/day`] } }, explanation: "Your daily calorie need is the total energy your body uses in a day, including the calories burned at rest plus those burned by moving, working and exercising. This calculator estimates it by multiplying your basal metabolic rate (BMR) — the calories you burn at rest — by an activity multiplier that reflects how active you are.\n\nEnter your BMR from the BMR calculator and choose a multiplier between 1 and 2.5: 1 means no activity beyond resting, and higher values mean more daily activity. The result is a starting point for planning meals or a weight goal, not a prescription. It is informational and is not a substitute for professional medical advice.", example: { inputs: "BMR 1,649 calories/day, activity multiplier 1.55.", calculation: "1,649 × 1.55 = 2,555.95.", result: "2,556 calories/day." }, faq: [["What activity multiplier should I choose?", "The calculator does not label activity levels, so judge your own day: 1 means resting only, and the number rises with how much you move. If unsure, start near the middle of the range and adjust if your weight does not move as expected."], ["I want to lose weight. Should I eat fewer calories than this result?", "This calculator only estimates the calories that maintain your current weight. Eating less than that generally leads to weight loss, but how much less is safe depends on your health, so ask a doctor before cutting calories sharply."], ["Why does the result change if I re-enter my BMR from the BMR calculator?", "The calorie calculator multiplies whatever BMR you enter, so a different BMR gives a different result. Small rounding differences in the BMR you enter usually change the answer by only a calorie or two."]], related: ['bmr', 'water-intake'],
  },
  {
    id: 'water-intake', name: 'Water Intake Calculator', description: 'Estimate a daily water intake target from body weight.', category: 'health', icon: '◇', path: '/calculators/water-intake', fields: [field('weight', 'Weight', 'kg', 1, 500), field('activity', 'Exercise time', 'minutes/day', 0, 300)], formula: 'Base water = weight × 35 ml, plus 350 ml per 30 minutes of exercise', calculate: ({ weight, activity }) => { const ml = weight * 35 + activity / 30 * 350; return { headline: `${n(ml / 1000)} liters/day`, details: ['Needs vary with climate, health, diet, and activity.'], steps: [`${n(weight)} × 35 = ${n(weight * 35)} ml base`, `Exercise adjustment: ${n(activity / 30 * 350)} ml`, `Total: ${n(ml)} ml`] } }, explanation: "This calculator estimates how much water you should drink in a day, based on your body weight and how much you exercise. The estimate starts from a simple rule of thumb — about 35 millilitres of water per kilogram of body weight — and then adds extra for exercise, because you lose more fluid when you sweat.\n\nThe result is a daily target in litres, not a strict rule. Your real needs vary with the weather, your diet, your health and how hard you exercise. Thirst is a useful guide too. The result is informational and is not a substitute for professional medical advice.", example: { inputs: "Weight 70 kg, exercise 30 minutes per day.", calculation: "Base: 70 × 35 = 2,450 ml. Exercise: 30 ÷ 30 × 350 = 350 ml. Total: 2,450 + 350 = 2,800 ml.", result: "2.8 liters/day." }, faq: [["Does the 35 ml per kilogram rule apply to everyone?", "No, it is a rough average for healthy adults. Children, older people and people with certain health conditions have different needs, and hot weather or illness can raise them further, so use the result as a guide only."], ["Does food count toward my daily water intake?", "Yes, in real life it does — many foods, especially fruit, vegetables and soups, contain a lot of water. This calculator estimates drinking water only, so your total fluid intake from food and drink combined will be higher."], ["Can I drink too much water?", "Yes, it is possible to overdo it, especially by drinking very large amounts in a short time, which can dilute the salts in your blood. Spread your intake through the day and do not force yourself to drink far beyond thirst."]], related: ['calorie', 'bmr'],
  },
]

const financeFields = (principalLabel = 'Principal', principalMin = 0.01): CalculatorField[] => [field('principal', principalLabel, '$', principalMin, 100000000), field('rate', 'Annual interest rate', '%', 0, 100), field('years', 'Term', 'years', 0.1, 100)]
const loanCalc = ({ principal, rate, years }: Record<string, number>): CalculationResult => { const months = years * 12; const monthlyRate = rate / 1200; const payment = monthlyRate === 0 ? principal / months : principal * monthlyRate * (1 + monthlyRate) ** months / ((1 + monthlyRate) ** months - 1); const total = payment * months; return { headline: `$${money(payment)} / month`, details: [`Total paid: $${money(total)}`, `Total interest: $${money(total - principal)}`], steps: [`${n(months, 0)} monthly payments`, `Monthly rate: ${n(monthlyRate * 100, 4)}%`] } }
// F-01 (Phase 3 corrective action): at 0% interest the annuity formula would
// divide by the rate. The old code guarded with (rate / 100 || 1), which made
// the contributions term 0 at 0% instead of contributions x years. For any
// positive rate this is algebraically identical to the previous formula.
const annuityValue = (contributions: number, rate: number, years: number): number =>
  rate === 0 ? contributions * years : contributions * (((1 + rate / 100) ** years - 1) / (rate / 100))
const compoundCalc = ({ principal, rate, years, contributions = 0 }: Record<string, number>): CalculationResult => { const value = principal * (1 + rate / 100) ** years + annuityValue(contributions, rate, years); return { headline: `$${money(value)}`, details: [`Growth: $${money(value - principal - contributions * years)}`], steps: [`Future value = principal × (1 + rate)^years`, `Estimated balance: $${money(value)}`] } }
// Savings: annual deposits compound annually, monthly deposits compound monthly
// (end of each month). With monthly contributions = 0 this is identical to compoundCalc.
const savingsCalc = ({ principal, rate, years, contributions = 0, monthlyContributions = 0 }: Record<string, number>): CalculationResult => {
  const annualValue = principal * (1 + rate / 100) ** years + annuityValue(contributions, rate, years)
  const monthlyRate = rate / 1200
  const months = years * 12
  const monthlyValue = monthlyContributions === 0 || monthlyRate === 0 ? monthlyContributions * months : monthlyContributions * (((1 + monthlyRate) ** months - 1) / monthlyRate)
  const value = annualValue + monthlyValue
  const totalDeposited = principal + contributions * years + monthlyContributions * months
  return { headline: `$${money(value)}`, details: [`Growth: $${money(value - totalDeposited)}`, 'Annual deposits compound annually; monthly deposits compound monthly (end of month).'], steps: [`Starting balance grows to $${money(principal * (1 + rate / 100) ** years)}`, `Annual deposits add $${money(annualValue - principal * (1 + rate / 100) ** years)}`, `Monthly deposits add $${money(monthlyValue)}`, `Estimated balance: $${money(value)}`] }
}

const finance: Calculator[] = [
  { id: 'loan', name: 'Loan Calculator', description: 'Estimate monthly payments, total interest, and total cost.', category: 'finance', icon: '$', path: '/calculators/loan', fields: financeFields('Loan amount'), formula: 'Payment = P × r(1+r)ⁿ ÷ ((1+r)ⁿ−1)', calculate: loanCalc, explanation: "A loan calculator estimates the fixed monthly payment on a loan from the amount borrowed, the annual interest rate and the term in years. It is useful before borrowing, because it shows what the loan costs each month and how much interest you pay overall, so you can compare offers or check whether a loan fits your budget.\n\nIt uses the standard amortisation formula: the annual rate is divided by 12 to get a monthly rate, and the payment is set so the loan is fully repaid in equal monthly instalments. The result shows the monthly payment, the total paid and the total interest. It assumes a fixed rate and equal payments, and it excludes lender fees, insurance and other charges.", example: { inputs: "A $10,000 loan at 12% annual interest over 1 year.", calculation: "The monthly rate is 12% ÷ 12 = 1% per month, with 12 payments. Using the amortisation formula, $10,000 × 0.01 × 1.01^12 ÷ (1.01^12 − 1) = $888.49 per month.", result: "Monthly payment $888.49, total paid $10,661.85, total interest $661.85." }, faq: [["Why does a longer loan term lower the monthly payment but raise the total interest?", "Spreading the loan over more months shrinks each payment, but interest is charged for longer, so the lender collects more in total. Compare the total interest, not just the monthly figure, when choosing a term."], ["What happens if I enter a 0% interest rate?", "The calculator divides the amount by the number of months, so a $12,000 loan over one year gives $1,000 a month with no interest. That matches a genuine interest-free loan with no fees."], ["Why is the payment the calculator shows different from a lender’s quote?", "Lenders often add fees, insurance or charges that this calculator does not include, and your rate may differ from the one you entered. Use the result as a comparison figure, then check the lender’s full terms."]], related: ['mortgage', 'compound-interest'] },
  { id: 'mortgage', name: 'Mortgage Calculator', description: 'Estimate a home loan payment and long-term interest.', category: 'finance', icon: '⌂', path: '/calculators/mortgage', fields: financeFields('Home price'), formula: 'Monthly principal and interest payment using amortization.', calculate: loanCalc, explanation: "A mortgage calculator estimates the monthly payment on a home loan from the home price, the annual interest rate and the term in years. It helps a buyer see what a house would really cost each month before making an offer, and compare how different prices, rates and terms change the payment.\n\nIt uses the same amortisation formula as a loan: the annual rate is divided by 12, and the payment is set so the loan is fully repaid in equal monthly instalments. The result shows the monthly payment, the total paid and the total interest. The figure covers principal and interest only — it excludes a down payment, property tax, insurance, HOA fees and PMI, so the full cost of owning the home will be higher.", example: { inputs: "A $200,000 home loan at 6% annual interest over 30 years.", calculation: "The monthly rate is 6% ÷ 12 = 0.5% per month, with 360 payments. Using the amortisation formula, $200,000 × 0.005 × 1.005^360 ÷ (1.005^360 − 1) = $1,199.10 per month.", result: "Monthly payment $1,199.10, total paid $431,676.38, total interest $231,676.38." }, faq: [["Why is the total interest so large on a 30-year mortgage?", "Interest is charged on the balance every month for 30 years, and the balance falls slowly at first, so most early payments go to interest. A shorter term or a larger payment cuts the total interest sharply."], ["Does the result include taxes and insurance?", "No. This calculator covers principal and interest only. Property tax, home insurance, HOA fees and PMI are charged separately by your lender or local authority, so budget for those on top of this figure."], ["How does a higher interest rate change the payment?", "A higher rate raises the monthly payment and the total interest, sometimes by tens of thousands over the life of the loan. Even a small rate difference matters, which is why comparing rates before choosing a lender is worthwhile."]], related: ['loan', 'investment-return'] },
  { id: 'compound-interest', name: 'Compound Interest Calculator', description: 'Project how savings grow with compound interest.', category: 'finance', icon: '↗', path: '/calculators/compound-interest', fields: [...financeFields(), field('contributions', 'Annual contribution', '$', 0, 10000000)], formula: 'A = P(1+r)ⁿ + contributions × (((1+r)ⁿ−1)/r)', calculate: compoundCalc, explanation: "A compound interest calculator projects how money grows when the interest earned each year is added to the balance and then earns interest itself. It is useful for savings and investments, because it shows how starting early and adding regular contributions can build a much larger balance over time.\n\nThe future value is the starting amount grown by the annual rate, plus any annual contributions grown in the same way. The calculator assumes the rate stays the same every year and that contributions are made once a year. It does not include taxes, fees or inflation, so treat the result as a projection, not a promise.", example: { inputs: "$1,000 starting balance, $100 contributed each year, 10% annual interest, 2 years.", calculation: "The $1,000 grows to $1,000 × 1.10² = $1,210.00. The annual contributions grow to $100 × ((1.10² − 1) ÷ 0.10) = $210.00. Added together, the balance is $1,420.00.", result: "Estimated balance $1,420.00, of which $220.00 is growth." }, faq: [["Why does the balance grow faster in later years?", "Each year’s interest is calculated on a bigger balance, because earlier interest has been added to it. That compounding effect is small at first and much larger later, which is why starting early matters so much."], ["What should I enter for the interest rate?", "Use the rate your savings account or investment is expected to earn each year, after any fees. If the rate is uncertain, try a lower and a higher rate to see the range of possible outcomes."], ["Why is the result an estimate rather than a guarantee?", "Real rates change, and taxes, fees and inflation are not included in this calculation. The result shows what would happen if the rate stayed exactly as entered for the whole term."]], related: ['savings', 'investment-return'] },
  { id: 'savings', name: 'Savings Calculator', description: 'Estimate future savings from a starting balance, annual deposits and monthly deposits. Annual deposits compound annually; monthly deposits compound monthly.', category: 'finance', icon: '▣', path: '/calculators/savings', fields: [...financeFields('Starting balance'), field('contributions', 'Annual deposit', '$', 0, 10000000), field('monthlyContributions', 'Monthly deposit', '$', 0, 1000000)], formula: 'Future value with annual compounding for annual deposits and monthly compounding for monthly deposits.', calculate: savingsCalc, explanation: "A savings calculator estimates the future balance of a savings plan from a starting balance, an annual interest rate, the number of years, and deposits made either once a year or every month. It is useful for planning a holiday fund, a house deposit or an emergency fund, because it shows how regular deposits add up over time.\n\nAnnual deposits are assumed to compound once a year, while monthly deposits are assumed to be made at the end of each month and compound monthly. The calculator assumes the rate stays the same and does not include taxes, fees or withdrawals, so the result is a projection of what steady saving could achieve.", example: { inputs: "$1,000 starting balance, $100 deposited each month, 5% annual interest, 5 years, no annual deposits.", calculation: "The $1,000 grows to $1,000 × 1.05^5 = $1,276.28. The monthly deposits, made at the end of each month at a monthly rate of 5% ÷ 12, grow to $6,800.61. Added together, the balance is $8,076.89.", result: "Estimated balance $8,076.89. You deposited $7,000.00 in total, so $1,076.89 is growth." }, faq: [["What is the difference between an annual deposit and a monthly deposit?", "An annual deposit is added once a year and compounds yearly, while a monthly deposit is added at the end of each month and compounds monthly. Monthly deposits start earning interest sooner, so the same yearly total can grow slightly more when paid monthly."], ["What happens if I set the interest rate to 0%?", "With no interest, the balance is simply the starting amount plus every deposit, with nothing added. The calculator still adds the deposits up correctly, so it works for a plain cash-saving plan too."], ["Does the result include interest I would pay tax on?", "No. The calculator shows the balance before any tax on the interest earned. Depending on where you live, some of the interest may be taxable, so the amount you keep could be lower."], ["Why is the balance higher than the total I deposited?", "The difference is interest. Your deposits earn interest, and that interest is added to the balance and earns interest too. In the example, $7,000 deposited grows to $8,076.89, so $1,076.89 is interest."]], related: ['compound-interest', 'retirement'] },
  { id: 'investment-return', name: 'Investment Return Calculator', description: 'Estimate an investment’s return and ending value.', category: 'finance', icon: '◒', path: '/calculators/investment-return', fields: [...financeFields('Initial investment'), field('contributions', 'Annual contribution', '$', 0, 10000000)], formula: 'Return = ending value − contributions and initial investment.', calculate: compoundCalc, explanation: "An investment return calculator estimates the future value of an investment from the initial amount, an annual return rate, the number of years and any regular annual contributions. It helps an investor compare scenarios, such as starting with more money, contributing more each year or investing for longer.\n\nThe initial investment grows by the annual rate each year, and each annual contribution grows in the same way from the year it is made. The calculator assumes a steady rate every year and does not include taxes, fees, inflation or market ups and downs, so the result is a projection, not a forecast of what will actually happen.", example: { inputs: "$10,000 initial investment, $2,000 contributed each year, 8% annual return, 15 years.", calculation: "The $10,000 grows to $10,000 × 1.08^15 = $31,721.69. The annual contributions grow to $2,000 × ((1.08^15 − 1) ÷ 0.08) = $54,304.23. Added together, the ending value is $86,025.92.", result: "Estimated ending value $86,025.92, of which $46,025.92 is growth." }, faq: [["How is this different from the compound interest calculator?", "Both use the same growth formula. This one is framed for investments: the starting amount is your initial investment and the result is an ending value. Use whichever wording matches what you are planning."], ["What return rate should I enter?", "Use a realistic long-term average for the type of investment, after fees. A cautious estimate is safer than an optimistic one, because real returns vary from year to year and are never guaranteed."], ["Why does investing for longer make such a big difference?", "Returns compound: gains from earlier years are reinvested and earn returns of their own. Extra years at the end add far more than extra years at the start, because the balance is much larger by then."]], related: ['compound-interest', 'retirement'] },
  { id: 'retirement', name: 'Retirement Calculator', description: 'Project a retirement balance from contributions and growth.', category: 'finance', icon: '◎', path: '/calculators/retirement', fields: [...financeFields('Current savings', 0), field('contributions', 'Annual contribution', '$', 0, 10000000)], formula: 'Projected balance using annual compounding.', calculate: compoundCalc, explanation: "A retirement calculator projects the balance you could build for retirement from your current savings, an annual contribution and an assumed annual growth rate over the years until you retire. It helps you see whether your current saving plan is on track, and how saving more or starting earlier changes the outcome.\n\nYour current savings grow by the annual rate, and each year’s contribution grows in the same way. You can start with $0 if you have not saved yet. The calculator assumes a steady rate and does not include taxes, fees, inflation, employer contributions or withdrawals, so treat the result as a planning estimate, not a promise.", example: { inputs: "$0 current savings, $6,000 contributed each year, 7% annual growth, 30 years.", calculation: "With no starting balance, the balance comes entirely from contributions: $6,000 × ((1.07^30 − 1) ÷ 0.07) = $566,764.72.", result: "Projected retirement balance $566,764.72, from $180,000.00 of contributions." }, faq: [["I have no savings yet. Can I still use this calculator?", "Yes. Enter $0 as your current savings and your planned yearly contribution. The result shows what steady contributions alone could build, which is a useful starting point for a new retirement plan."], ["How does the growth rate change the result?", "A higher rate grows the balance much faster over decades, but it also means taking more investment risk. Try a lower rate as well, so your plan still works if returns turn out to be modest."], ["Does the result account for inflation or tax?", "No. The figure is in future dollars before tax and before adjusting for rising prices. Your contributions will buy less in 30 years than they do today, so the real value of the balance will be lower."]], related: ['savings', 'investment-return'] },
  { id: 'vat', name: 'VAT Calculator', description: 'Add VAT to a net price, or remove VAT from a gross price.', category: 'finance', icon: '%', path: '/calculators/vat', fields: [selectField('mode', 'Calculation', [{ value: 0, label: 'Add VAT (net price → gross price)' }, { value: 1, label: 'Remove VAT (gross price → net price)' }]), field('principal', 'Price', '$', 0.01, 100000000), field('rate', 'VAT rate', '%', 0, 100)], formula: 'Add VAT: gross = net + net × rate. Remove VAT: net = gross ÷ (1 + rate).', calculate: ({ principal, rate, mode = 0 }) => { if (mode === 1) { const net = principal / (1 + rate / 100); const tax = principal - net; return { headline: `$${money(net)} excluding VAT`, details: [`VAT amount: $${money(tax)}`, `Gross price: $${money(principal)}`], steps: [`${money(principal)} ÷ (1 + ${n(rate)}%) = $${money(net)}`] } } const tax = principal * rate / 100; return { headline: `$${money(principal + tax)} including VAT`, details: [`VAT amount: $${money(tax)}`, `Net price: $${money(principal)}`], steps: [`${money(principal)} × ${n(rate)}% = $${money(tax)}`] } }, explanation: "A VAT calculator works out the tax on a price in two directions. Add VAT to a net price to get the gross price a customer pays, or remove VAT from a gross price to find the net price and the tax included in it. It is useful for shop owners, freelancers and anyone preparing invoices or quotes.\n\nTo add VAT, the tax is the net price multiplied by the rate, and the gross price is the net price plus that tax. To remove VAT, the net price is the gross price divided by one plus the rate. The calculator handles one rate at a time and does not include other taxes, discounts or shipping.", example: { inputs: "A net price of $100 with a VAT rate of 20%, adding VAT.", calculation: "The VAT is $100 × 20% = $20.00. The gross price is $100 + $20.00 = $120.00.", result: "Gross price $120.00 including VAT, VAT amount $20.00." }, faq: [["What is the difference between a net price and a gross price?", "The net price excludes VAT; the gross price includes it. A shop lists the gross price to customers, while a business usually records the net price and claims the VAT part separately."], ["Why can’t I just subtract 20% from $120 to remove 20% VAT?", "Because 20% of the gross price is $24, not $20. The VAT is 20% of the net price, so the correct net price is $120 ÷ 1.20 = $100.00, with $20.00 of tax."], ["Which VAT rate should I use?", "Use the rate that applies to the goods or services in your country, since rates differ by product and place. If you are unsure, check your local tax authority or ask an accountant."]], related: ['discount', 'profit-margin'] },
  { id: 'discount', name: 'Discount Calculator', description: 'Calculate sale price and savings from a discount.', category: 'finance', icon: '−', path: '/calculators/discount', fields: [field('principal', 'Original price', '$', 0.01, 100000000), field('rate', 'Discount', '%', 0, 100)], formula: 'Sale price = original price × (1 − discount rate)', calculate: ({ principal, rate }) => { const savings = principal * rate / 100; return { headline: `$${money(principal - savings)}`, details: [`You save: $${money(savings)}`], steps: [`${money(principal)} × ${n(rate)}% = $${money(savings)} saved`] } }, explanation: "A discount calculator works out the sale price of an item and how much you save, from the original price and the discount percentage. It is useful while shopping, during a sale, or when a business is setting prices, because it turns a percentage off into a clear price.\n\nThe amount saved is the original price multiplied by the discount rate, and the sale price is the original price minus that amount. The calculator applies a single percentage discount and does not include tax, shipping or extra offers, so the final amount at checkout may differ.", example: { inputs: "An item priced at $100 with a 25% discount.", calculation: "The amount saved is $100 × 25% = $25.00. The sale price is $100 − $25.00 = $75.00.", result: "Sale price $75.00, you save $25.00." }, faq: [["What does 25% off actually mean?", "It means you pay 75% of the original price. On a $100 item, the discount is $25 and you pay $75. The percentage always applies to the original price, not to an already reduced one."], ["Can I use this for two discounts in a row?", "Not directly. Two discounts do not simply add up: 20% off followed by 10% off is a 28% total reduction, not 30%. Apply the first discount, then calculate the second on the new price."], ["Why is the sale price different from the price at checkout?", "Taxes, shipping or other charges are added after the discount, and some stores exclude certain items from a sale. The calculator shows the discounted price before those extras."]], related: ['vat', 'profit-margin'] },
  { id: 'profit-margin', name: 'Profit Margin Calculator', description: 'Calculate gross profit and profit margin from cost and revenue.', category: 'finance', icon: '▰', path: '/calculators/profit-margin', fields: [field('revenue', 'Revenue', '$', 0.01, 100000000), field('cost', 'Cost', '$', 0, 100000000)], formula: 'Margin = (revenue − cost) ÷ revenue × 100', calculate: ({ revenue, cost }) => { const profit = revenue - cost; return { headline: `${n(profit / revenue * 100)}% profit margin`, details: [`Profit: $${money(profit)}`], steps: [`$${money(revenue)} − $${money(cost)} = $${money(profit)}`, `$${money(profit)} ÷ $${money(revenue)} × 100 = ${n(profit / revenue * 100)}%`] } }, explanation: "A profit margin calculator works out how much of your revenue is profit, from the revenue and the cost of what you sold. It is useful for a business owner or seller who wants to know whether prices cover costs and how much of each sale is kept as profit.\n\nProfit is revenue minus cost, and the margin is that profit divided by revenue, shown as a percentage. The calculator uses only the revenue and cost you enter. It does not include other expenses such as rent, wages or tax, so the margin it shows is the gross margin on the sale itself, not the profit of the whole business.", example: { inputs: "Revenue of $100 and cost of $60.", calculation: "The profit is $100 − $60 = $40.00. The margin is $40.00 ÷ $100 × 100 = 40%.", result: "Profit margin 40%, profit $40.00." }, faq: [["What is the difference between profit margin and markup?", "Margin is profit as a share of the selling price, while markup is profit as a share of the cost. On a $60 cost sold for $100, the margin is 40% but the markup is about 67%."], ["Can the profit margin be negative?", "Yes. If the cost is higher than the revenue, the calculator shows a negative margin, which means you lose money on the sale. A negative margin is a warning that the price or the cost needs to change."], ["What is a good profit margin?", "It depends on the business: a grocery shop may run on a small margin with high volume, while a service business may need a larger one. Compare your margin with similar businesses rather than aiming for one fixed number."]], related: ['discount', 'vat'] },
]

const math: Calculator[] = [
  { id: 'percentage', name: 'Percentage Calculator', description: 'Find X% of Y, or find what percentage X is of Y.', category: 'math', icon: '%', path: '/calculators/percentage', fields: [selectField('mode', 'Calculation', [{ value: 0, label: 'X% of Y' }, { value: 1, label: 'X is what % of Y' }]), field('principal', 'First number (X)', '', -100000000, 100000000), field('rate', 'Second number (Y) or percentage', '', -100000, 100000)], formula: 'X% of Y = X × Y ÷ 100. X is what % of Y = X ÷ Y × 100.', calculate: ({ principal, rate, mode = 0 }) => { if (mode === 1) { if (rate === 0) return { headline: 'Invalid result', details: ['The second number cannot be zero.'], steps: [] }; const value = principal / rate * 100; return { headline: `${n(value)}%`, details: [`${n(principal)} is ${n(value)}% of ${n(rate)}`], steps: [`${n(principal)} ÷ ${n(rate)} × 100 = ${n(value)}%`] } } const value = principal * rate / 100; return { headline: n(value), details: [`${n(rate)}% of ${n(principal)} is ${n(value)}`], steps: [`${n(principal)} × ${n(rate)} ÷ 100 = ${n(value)}`] } }, explanation: "The Percentage Calculator answers two everyday percentage questions. Choose 'X% of Y' to find a part of a number, such as a discount or a tip. Choose 'X is what % of Y' to compare two numbers, such as a test score or a price increase.\n\nFor 'X% of Y' it multiplies X by Y and divides by 100. For 'X is what % of Y' it divides X by Y and multiplies by 100. The result is the percentage or the part you asked for, so you can see the share or the amount directly.", example: { inputs: "X = 12.5, Y = 80, mode \"X% of Y\"", calculation: "12.5 × 80 ÷ 100 = 10", result: "10" }, faq: [["What happens if I enter zero as the second number in \"X is what % of Y\"?", "The calculator shows 'Invalid result', because dividing by zero has no answer. Enter a non-zero second number to compare against, or switch to 'X% of Y' if zero is the value you actually mean."], ["Can I use negative numbers or decimals?", "Yes. Both fields accept decimals and negative numbers, so you can work out a percentage loss, a change below zero, or a precise share such as 12.5% of a price."], ["Which mode do I need for a discount?", "Use 'X% of Y': enter the discount percent as X and the original price as Y, and the answer is the amount saved. Subtract that from the price to get what you pay."]], related: ['discount', 'average'] },
  { id: 'scientific', name: 'Scientific Calculator', description: 'Evaluate arithmetic expressions with scientific functions: square roots, powers, trigonometry, logarithms and more.', category: 'math', icon: '∑', path: '/calculators/scientific', fields: [{ id: 'expression', label: 'Expression (e.g. 2 + 2 × 5)' }], formula: 'Standard arithmetic order of operations. Use ^ for powers and sqrt(...) for square roots.', calculate: ({ expression }) => calculateScientific({ expression: String(expression), angleMode: 'deg' }), explanation: "The Scientific Calculator evaluates a whole expression in one go, using standard order of operations: powers first, then multiplication and division, then addition and subtraction. You can type an expression or tap the on-screen keypad, and brackets let you group parts of a calculation.\n\nIt supports square roots, nth roots, powers, factorials, pi and e, plus logarithms (log is base 10, ln is the natural log) and trigonometry — sin, cos, tan and their inverses. Angles are in degrees by default; switch to RAD if your angles are in radians. The result is shown rounded to 8 decimal places.", example: { inputs: "Expression: sqrt(16) + 2^3", calculation: "sqrt(16) = 4 and 2^3 = 8, so 4 + 8 = 12", result: "12" }, faq: [["Why does -2^2 give -4 instead of 4?", "The minus sign applies to the whole power, so -2^2 is read as -(2^2), which is -4. If you mean negative two squared, write it with brackets: (-2)^2 gives 4."], ["How do I switch between degrees and radians for sin and cos?", "Use the DEG/RAD switch above the keypad. DEG is the default, so sin(30) is 0.5. In RAD mode the same button treats 30 as radians, which gives a different answer, so check the mode first."], ["What does \"Invalid expression\" mean?", "It means the calculator could not read what you typed — for example a missing bracket, a function it does not recognise, or two operators in a row. Check the expression, close every bracket, and try again."]], related: ['percentage', 'fraction'] },
  { id: 'age', name: 'Age Calculator', description: 'Calculate age from a full date of birth (day, month and year).', category: 'math', icon: '◷', path: '/calculators/age', fields: [{ id: 'birthDay', label: 'Birth day', min: 1, max: 31, step: '1' }, { id: 'birthMonth', label: 'Birth month', min: 1, max: 12, step: '1' }, { id: 'birthYear', label: 'Birth year', min: 1900, max: 2100, step: '1' }], formula: 'Age = full years since the date of birth, counting whether this year\'s birthday has passed.', calculate: ({ birthYear, birthMonth = 1, birthDay = 1 }) => { const today = new Date(); const birth = new Date(birthYear, birthMonth - 1, birthDay); if (birth.getDate() !== birthDay || birth.getMonth() !== birthMonth - 1) return { headline: 'Invalid date', details: ['That day does not exist in that month (for example, 30 February).'], steps: [] }; let value = today.getFullYear() - birthYear; if (today.getMonth() < birthMonth - 1 || (today.getMonth() === birthMonth - 1 && today.getDate() < birthDay)) value -= 1; return { headline: `${n(value, 0)} years`, details: [`Date of birth: ${birthDay}/${birthMonth}/${birthYear}.`, `Today: ${today.getDate()}/${today.getMonth() + 1}/${today.getFullYear()}.`], steps: [`${today.getFullYear()} − ${birthYear} = ${today.getFullYear() - birthYear} years, adjusted for whether this year's birthday has passed`] } }, explanation: "The Age Calculator works out a person's age in full years from their date of birth. Enter the day, month and year of birth, and it counts how many birthdays have passed up to today — so someone whose birthday is later this year is still counted at last year's age.\n\nIt rejects dates that do not exist, such as 30 February, instead of guessing. The result is simply an age in years — useful for forms, eligibility checks and anniversaries — and it is informational only, not a substitute for official records.", example: { inputs: "Born 15 June 1990; reference date 20 November 2026", calculation: "2026 − 1990 = 36, and the 15 June birthday has already passed in 2026, so no adjustment is needed", result: "36 years" }, faq: [["Why is my age one year less than the year difference?", "Your age only increases on your birthday. If this year's birthday has not happened yet, the calculator subtracts one from the year difference, so the age shown is the number of birthdays you have actually had."], ["Can I enter only a birth year?", "Yes — leave the day and month at 1 January and the calculator treats 1 January of that year as the birth date. The age is then correct as long as the birthday has passed by the date you check it."], ["Why does it say \"Invalid date\" for 30 February?", "February never has 30 days, so that date does not exist in any year. The calculator refuses it rather than silently shifting it to another day. Check the month and day and enter the real birth date."]], related: ['average', 'percentage'] },
  { id: 'average', name: 'Average Calculator', description: 'Calculate the mean of a set of numbers.', category: 'math', icon: '≈', path: '/calculators/average', fields: [field('number1', 'Number 1', '', -100000000, 100000000), field('number2', 'Number 2', '', -100000000, 100000000), field('number3', 'Number 3', '', -100000000, 100000000)], formula: 'Mean = sum of values ÷ number of values', calculate: ({ number1, number2, number3 }) => { const value = (number1 + number2 + number3) / 3; return { headline: n(value), details: [`Average of ${n(number1)}, ${n(number2)}, and ${n(number3)}`], steps: `(${n(number1)} + ${n(number2)} + ${n(number3)}) ÷ 3 = ${n(value)}`.split('\n') } }, explanation: "The Average Calculator finds the mean of exactly three numbers. Enter one number in each box — for example three test scores, three prices or three measurements — and it adds them together and divides by three.\n\nThe mean is a quick summary of the group: it shows the value each number would have if the total were shared equally. It is handy for grades, averages of a few readings or comparing small sets of figures, and it accepts decimals and negative numbers.", example: { inputs: "Numbers: 10, 20, 30", calculation: "(10 + 20 + 30) ÷ 3 = 60 ÷ 3 = 20", result: "20" }, faq: [["Why does it ask for exactly three numbers?", "This calculator is built for three values only — for example three test scores or three monthly bills. If you have more numbers, average them in groups of three or use the mean of the group totals instead."], ["Does the average change if I reorder the numbers?", "No. Addition works in any order, so the total — and therefore the mean — is the same no matter which box each number goes in. Only the numbers themselves affect the result."], ["Can the average be lower than my smallest number?", "No — the mean of three numbers always sits between the smallest and the largest. If your result falls outside that range, one of the numbers was probably typed incorrectly, so check your entries."]], related: ['percentage', 'ratio'] },
  { id: 'ratio', name: 'Ratio Calculator', description: 'Scale a ratio to find an equivalent value.', category: 'math', icon: '∶', path: '/calculators/ratio', fields: [field('a', 'First ratio value', '', 0.0001, 100000000), field('b', 'Second ratio value', '', 0.0001, 100000000), field('c', 'Known value', '', 0.0001, 100000000)], formula: 'a:b = c:x, so x = b × c ÷ a', calculate: ({ a, b, c }) => { const value = b * c / a; return { headline: n(value), details: [`Equivalent ratio: ${n(c)}:${n(value)}`], steps: [`${n(b)} × ${n(c)} ÷ ${n(a)} = ${n(value)}`] } }, explanation: "The Ratio Calculator scales a ratio to find a missing value. Give it a ratio a:b and one known value, and it works out the matching value in the same proportion — useful for recipes, scale drawings, mixtures and exchange rates.\n\nIt uses the rule a:b = c:x, so the answer is x = b × c ÷ a. The two sides stay in the same proportion, so doubling the known value doubles the answer. The result is the equivalent value, shown with up to two decimal places.", example: { inputs: "Ratio a:b = 2:3, known value c = 10", calculation: "x = 3 × 10 ÷ 2 = 15", result: "15" }, faq: [["Which number goes in which box?", "Enter the two ratio numbers as a and b, then the known value as c — the value that matches a. The answer x is the value that matches b in the same proportion, so keep the order the same on both sides."], ["Can I use a ratio with decimals, like 1.5:2?", "Yes, all three fields accept decimals, so ratios such as 1.5:2 work exactly like whole-number ratios. The result may have decimals too, and it is rounded to two decimal places."], ["Can I use zero in a ratio?", "No — all three values must be greater than zero, because a ratio with a zero side has no meaningful proportion to scale. If your real-world numbers include zero, the ratio does not apply and the calculator will not accept the entry."]], related: ['fraction', 'average'] },
  { id: 'fraction', name: 'Fraction Calculator', description: 'Add two fractions and simplify the result.', category: 'math', icon: '½', path: '/calculators/fraction', fields: [{ id: 'a', label: 'First numerator', min: -100000, max: 100000, step: '1' }, { id: 'b', label: 'First denominator', min: 1, max: 100000, step: '1' }, { id: 'c', label: 'Second numerator', min: -100000, max: 100000, step: '1' }, { id: 'd', label: 'Second denominator', min: 1, max: 100000, step: '1' }], formula: 'a/b + c/d = (ad + bc) / bd', calculate: ({ a, b, c, d }) => { const numerator = a * d + c * b; const denominator = b * d; const gcd = (x: number, y: number): number => y ? gcd(y, x % y) : Math.abs(x); const divisor = gcd(numerator, denominator); return { headline: `${numerator / divisor}/${denominator / divisor}`, details: [`Decimal: ${n(numerator / denominator)}`], steps: [`(${a} × ${d} + ${c} × ${b}) ÷ (${b} × ${d})`, `Simplified: ${numerator / divisor}/${denominator / divisor}`] } }, explanation: "The Fraction Calculator adds two fractions and simplifies the answer. Enter each fraction as a numerator over a denominator — for example 1/2 and 1/3 — and it combines them into a single fraction in its lowest terms.\n\nIt uses the rule a/b + c/d = (ad + bc) / bd, then divides the top and bottom by their greatest common divisor. The result is shown as a simplified fraction, with its decimal value underneath, so you can check it against a decimal answer.", example: { inputs: "Fractions: 1/2 and 1/3", calculation: "(1 × 3 + 1 × 2) ÷ (2 × 3) = 5 ÷ 6 = 5/6", result: "5/6" }, faq: [["Can I add fractions with different denominators?", "Yes, that is exactly what this calculator is for. It converts both fractions to a common denominator by multiplying the denominators, adds the numerators, and then simplifies the result."], ["Why is my answer a smaller fraction than the ones I entered?", "Simplifying divides the top and bottom by their greatest common divisor, which only changes how the fraction looks — not its value. For example 2/4 and 1/2 are the same amount written differently."], ["Can I use negative fractions or a zero denominator?", "Negative numerators are allowed, so you can add or subtract fractional amounts. A denominator of zero is never allowed, because division by zero has no meaning — the calculator requires denominators of 1 or more."]], related: ['ratio', 'scientific'] },
]

const conversion = (id: string, name: string, description: string, icon: string, units: string[], convert: (value: number, unit: number) => number, formula: string, explanation: string, example: CalculatorExample, faq: [string, string][]): Calculator => ({ id, name, description, category: 'conversion', icon, path: `/calculators/${id}`, fields: [field('value', 'Value', units[0], -100000000, 100000000), selectField('unit', 'Input unit', [{ value: 0, label: units[0] }, { value: 1, label: units[1] }])], formula, calculate: ({ value, unit }) => { const result = convert(value, unit); return { headline: n(result), details: [`Converted from ${units[unit]} to ${units[unit ? 0 : 1]}.`], steps: [`${n(value)} ${units[unit]} → ${n(result)} ${units[unit ? 0 : 1]}`] } }, explanation, example, faq, related: ['percentage'] })

const conversions = [
  conversion('length', 'Length Converter', 'Convert between meters and feet.', '↔', ['meters', 'feet'], (v, u) => u ? v / 3.28084 : v * 3.28084, '1 meter = 3.28084 feet', "Most of the world measures length in meters, while the United States still uses feet for everyday distances. This converter switches a measurement between meters and feet, so a room size, a person's height, or a running distance can be read in whichever unit makes sense to you.\n\nIt uses the exact factor 1 meter = 3.28084 feet. Enter a value, choose whether it is meters or feet, and the other unit is worked out at once. It is handy for travellers, builders, and anyone buying furniture or sports gear from a listing written in the other system.", { inputs: "100 meters, converting to feet", calculation: "100 × 3.28084 = 328.084", result: "328.08 feet" }, [["Why is the answer rounded to two decimal places?", "Results are rounded to two decimal places to keep them easy to read and use. For everyday lengths, the tiny amount lost by rounding is far smaller than any real measuring error, so the answer stays accurate enough for practical purposes."], ["Should I use meters or feet?", "Use meters in most countries and for science, sport, and international products. Use feet in the United States, especially for construction, real estate, and aviation, where feet remain the everyday unit."], ["Can I convert a person's height with this tool?", "Yes. Enter the height in meters to get feet, for example 1.8 meters becomes 5.91 feet. Note that people usually state height in feet and inches, so you would still need to turn the decimal part into inches yourself."]]),
  conversion('weight', 'Weight Converter', 'Convert between kilograms and pounds.', '↔', ['kilograms', 'pounds'], (v, u) => u ? v / 2.20462 : v * 2.20462, '1 kilogram = 2.20462 pounds', "Kilograms are the standard weight unit in most of the world, while pounds are used in the United States. This converter switches a weight between kilograms and pounds, which is useful for luggage, recipes, gym weights, and reading product labels from another country.\n\nIt uses the exact factor 1 kilogram = 2.20462 pounds. Enter a weight, choose its unit, and the other unit is calculated at once. That saves you from guessing when a scale, a recipe, or an airline limit is given in the unit you do not normally use.", { inputs: "70 kilograms, converting to pounds", calculation: "70 × 2.20462 = 154.3234", result: "154.32 pounds" }, [["Why does my luggage allowance look bigger in pounds?", "Because a pound is a smaller unit than a kilogram, the same bag gets a larger number in pounds. A 23-kilogram allowance is about 50.71 pounds, so the limit has not changed, only the unit has."], ["Is a pound the same as a kilogram?", "No. One kilogram equals 2.20462 pounds, so a kilogram is more than twice as heavy as a pound. A common mistake is multiplying when you should divide, which makes the answer wrong by a factor of about five."], ["Can I use this for cooking?", "Yes, for ingredient weights such as flour or meat. Enter the amount in kilograms or pounds and convert it. Cups and spoons measure volume rather than weight, so they need a different kind of conversion."]]),
  conversion('temperature', 'Temperature Converter', 'Convert Celsius and Fahrenheit.', '°', ['°C', '°F'], (v, u) => u ? (v - 32) * 5 / 9 : v * 9 / 5 + 32, '°F = °C × 9/5 + 32', "Celsius is used for weather and cooking in most of the world, while Fahrenheit is still the everyday scale in the United States. This converter switches a temperature between degrees Celsius and degrees Fahrenheit, so a forecast, an oven setting, or a body temperature can be understood in the scale you know.\n\nIt uses the formulas °F = °C × 9/5 + 32 and °C = (°F − 32) × 5/9. Enter a temperature, choose its scale, and the other value is calculated at once. The two scales do not share a zero point, so a simple addition or subtraction cannot convert them.", { inputs: "36.6 °C, converting to Fahrenheit", calculation: "36.6 × 9/5 + 32 = 65.88 + 32 = 97.88", result: "97.88 °F" }, [["Why can't I convert by just adding or subtracting 32?", "The scales have different zero points and different sized degrees. Water freezes at 0 °C but 32 °F, and one Celsius degree equals 1.8 Fahrenheit degrees, so both a shift and a scaling are needed."], ["What counts as a fever in Celsius?", "A body temperature of 38 °C or higher is generally considered a fever. That is 100.4 °F. Remember that a single reading is only a guide, and you should seek medical advice if you are worried."], ["Which scale do most countries use?", "Almost every country uses Celsius for weather, cooking, and daily life. Fahrenheit is mainly used in the United States and a few other places, which is why travellers and recipe readers often need to convert."]]),
  conversion('area', 'Area Converter', 'Convert square meters and square feet.', '□', ['m²', 'ft²'], (v, u) => u ? v / 10.7639 : v * 10.7639, '1 m² = 10.7639 ft²', "Floor space is measured in square meters in most of the world, but square feet are standard in the United States. This converter switches an area between square meters and square feet, which helps when reading a floor plan, comparing apartment sizes, or buying flooring and paint.\n\nIt uses the exact factor 1 square meter = 10.7639 square feet. Enter an area, choose its unit, and the other unit is calculated at once. Because area covers two dimensions, its factor is not the same as the length factor, so do not convert square meters with the meters-to-feet number.", { inputs: "20 square meters, converting to square feet", calculation: "20 × 10.7639 = 215.278", result: "215.28 square feet" }, [["Why can't I use the length factor for area?", "Area is two-dimensional, so the length factor gets squared. One square meter equals 10.7639 square feet, not 3.28084. Using the length factor would make a room look far smaller than it really is."], ["How do I work out a room's area before converting?", "Measure the length and width in the same unit and multiply them together. A room 4 meters long and 5 meters wide is 20 square meters, which you can then convert here to about 215.28 square feet."], ["Where are square feet most commonly used?", "Square feet are the standard unit for homes, offices, and land in the United States. Estate agents, builders, and flooring shops quote areas in square feet, while most other countries use square meters."]]),
  conversion('volume', 'Volume Converter', 'Convert liters and US gallons.', '◫', ['liters', 'US gallons'], (v, u) => u ? v * 3.78541 : v / 3.78541, '1 gallon = 3.78541 liters', "Liquid volume is measured in liters in most of the world, while US gallons are used in the United States. This converter switches a volume between liters and US gallons, which is useful for fuel, recipes, aquariums, and garden watering.\n\nIt uses the exact factor 1 US gallon = 3.78541 liters. Enter a volume, choose whether it is liters or US gallons, and the other unit is calculated at once. Remember that this converter uses the US gallon, which is smaller than the imperial gallon used in the United Kingdom.", { inputs: "10 liters, converting to US gallons", calculation: "10 ÷ 3.78541 = 2.6417", result: "2.64 US gallons" }, [["Is a US gallon the same as a UK gallon?", "No. A US gallon equals 3.78541 liters, while an imperial gallon equals about 4.546 liters. This converter uses the US gallon, so check which gallon a recipe or manual means before converting."], ["Why is the answer smaller when I convert liters to gallons?", "A gallon is a larger unit than a liter, so the same amount of liquid needs fewer gallons than liters. Ten liters is only 2.64 gallons because each gallon holds almost four liters."], ["Can I convert a recipe's liquid amounts with this tool?", "Yes, when the recipe uses liters or gallons. Enter the amount and convert it. Cups, tablespoons, and fluid ounces are different units, so they cannot be converted here."]]),
  conversion('speed', 'Speed Converter', 'Convert kilometers per hour and miles per hour.', '➜', ['km/h', 'mph'], (v, u) => u ? v * 1.60934 : v / 1.60934, '1 mph = 1.60934 km/h', "Road speeds are shown in kilometers per hour in most of the world, but miles per hour are used in the United States and the United Kingdom. This converter switches a speed between kilometers per hour and miles per hour, which helps when driving abroad or reading a speed limit.\n\nIt uses the exact factor 1 mile per hour = 1.60934 kilometers per hour. Enter a speed, choose its unit, and the other unit is calculated at once. That keeps you legal and safe instead of guessing what a foreign speed limit means in your usual unit.", { inputs: "100 kilometers per hour, converting to miles per hour", calculation: "100 ÷ 1.60934 = 62.1371", result: "62.14 mph" }, [["Why is the mph number always smaller than the km/h number?", "A mile is longer than a kilometer, so fewer miles are covered in the same hour. That is why 100 kilometers per hour is only 62.14 miles per hour, even though the car is travelling just as fast."], ["What is a 50 mph speed limit in km/h?", "A 50 mph limit equals 80.47 km/h. Multiply the miles per hour by 1.60934 to get kilometers per hour, so 50 × 1.60934 = 80.467, rounded to 80.47."], ["Does this work for running and cycling speeds too?", "Yes. Any speed given in kilometers per hour or miles per hour can be converted, whether it is a car on a motorway, a cyclist, or a runner tracking their pace."]]),
  conversion('time', 'Time Converter', 'Convert minutes and hours.', '◷', ['minutes', 'hours'], (v, u) => u ? v * 60 : v / 60, '1 hour = 60 minutes', "Minutes and hours are the two units we use most for everyday durations. This converter switches a length of time between minutes and hours, which is useful for schedules, workouts, cooking times, and working out how long a journey or a film will take.\n\nIt uses the exact factor 1 hour = 60 minutes. Enter a time, choose whether it is minutes or hours, and the other unit is calculated at once. Because time is counted in sixties rather than tens, the decimal answer needs a little care to read correctly.", { inputs: "90 minutes, converting to hours", calculation: "90 ÷ 60 = 1.5", result: "1.5 hours" }, [["Why is 90 minutes 1.5 hours and not 1.9 hours?", "Time is counted in sixties, not tens, so 0.5 of an hour is 30 minutes, not 50. Ninety minutes is one full hour plus 30 minutes, which is 1.5 hours in decimal form."], ["How do I convert 2 hours 45 minutes?", "Convert each part separately. Two hours is 120 minutes, and adding 45 minutes gives 165 minutes. You can also enter 165 minutes here to get 2.75 hours."], ["Can I convert days or seconds with this tool?", "No, this converter handles only minutes and hours. To convert days, multiply by 24 to get hours first; to convert seconds, divide by 60 to get minutes."]]),
  conversion('data-storage', 'Data Storage Converter', 'Convert gigabytes and megabytes.', '▦', ['gigabytes', 'megabytes'], (v, u) => u ? v / 1024 : v * 1024, '1 GB = 1024 MB', "File and storage sizes are usually given in gigabytes or megabytes. This converter switches a size between gigabytes and megabytes, which helps when checking whether a download, a video, or a set of photos will fit on a phone, a memory card, or a hard drive.\n\nIt uses the exact factor 1 gigabyte = 1024 megabytes, the binary counting that computers and operating systems use. Enter a size, choose whether it is gigabytes or megabytes, and the other unit is calculated at once, so you can compare a file directly with the free space your device reports.", { inputs: "2.5 gigabytes, converting to megabytes", calculation: "2.5 × 1024 = 2,560", result: "2,560 megabytes" }, [["Why 1024 and not 1000?", "Computers count in powers of two, so one gigabyte is 1024 megabytes. Some drive makers use 1000 instead, which is why a drive sold as 256 GB shows less than 256 GB on your computer."], ["How big is a photo or a song in megabytes?", "A typical phone photo is about 2 to 5 megabytes and a song is about 3 to 5 megabytes. At 5 megabytes each, 2,560 megabytes holds roughly 500 songs."], ["Does converting change the size of my file?", "No. Conversion only restates the same amount of data in a different unit. The file itself is untouched; 2.5 gigabytes and 2,560 megabytes describe exactly the same amount of storage."]]),
]

export const calculators = [...definitions, ...finance, ...math, ...conversions]
export const calculatorMap = new Map(calculators.map((calculator) => [calculator.id, calculator]))
